/// Evidence-ui-mm: conformance-backed rows (additive; the differential
/// `evidence()` helper above is untouched).
const fn evidence_conformance(
    dll: &'static str,
    export: &'static str,
    evidence_id: &'static str,
) -> ApiCoverageEvidence {
    ApiCoverageEvidence {
        dll,
        export,
        arch: ArchSet::Any,
        windows_version: WindowsVersion::Any,
        level: CoverageLevel::Conformance,
        evidence_id,
    }
}

/// Convenience constructor for `casa1-conformance:<suite>` rows (any arch,
/// any Windows version) owned by the evidence-crt-net pass.
const fn conformance(
    dll: &'static str,
    export: &'static str,
    evidence_id: &'static str,
) -> ApiCoverageEvidence {
    ApiCoverageEvidence {
        dll,
        export,
        arch: ArchSet::Any,
        windows_version: WindowsVersion::Any,
        level: CoverageLevel::Conformance,
        evidence_id,
    }
}

/// Look up oracle-backed coverage evidence for a (DLL, export, arch, winver)
/// key, returning the strongest applicable evidence row.
pub fn coverage_evidence_for(
    dll: &str,
    export: &str,
    arch: ArchSet,
    windows_version: WindowsVersion,
) -> Option<&'static ApiCoverageEvidence> {
    let dll_key = dll.to_ascii_lowercase();
    COVERAGE_EVIDENCE.iter().find(|row| {
        row.dll.eq_ignore_ascii_case(&dll_key)
            && row.export.eq_ignore_ascii_case(export)
            && (row.arch == ArchSet::Any || row.arch == arch)
            && (row.windows_version == WindowsVersion::Any
                || row.windows_version == windows_version)
    })
}

#[cfg(test)]
/// Resolve a `casa1-conformance:<suite>` evidence id to a REAL test
/// target: either a test file `tests/<suite>.rs` or a test function
/// `fn <suite>(` inside the crate sources.  Returns the unresolved ids.
///
/// KNOWN_SUITES is documentation only — it NEVER bypasses this check
/// (a registry row must name something that exists and runs).
fn unresolved_conformance_suites(rows: &[ApiCoverageEvidence]) -> Vec<String> {
    let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut unresolved = Vec::new();
    for row in rows {
        let Some(suite) = row.evidence_id.strip_prefix("casa1-conformance:") else {
            continue;
        };
        if manifest_dir
            .join("tests")
            .join(format!("{suite}.rs"))
            .is_file()
        {
            continue;
        }
        let mut found = false;
        let mut stack = vec![manifest_dir.join("src")];
        while let Some(dir) = stack.pop() {
            let Ok(entries) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    stack.push(path);
                } else if path.extension().is_some_and(|e| e == "rs")
                    && std::fs::read_to_string(&path)
                        .is_ok_and(|text| text.contains(&format!("fn {suite}(")))
                {
                    found = true;
                    break;
                }
            }
            if found {
                break;
            }
        }
        if !found {
            unresolved.push(row.evidence_id.to_string());
        }
    }
    unresolved.sort();
    unresolved.dedup();
    unresolved
}

